begin;
do $$ declare a uuid;b uuid;p uuid;other_p uuid;rel uuid;tmp uuid;n timestamptz:='2026-11-26T10:00:00-07';v jsonb;begin
select id into a from gesta_bank.professional_demo where fixture='PRO-DEMO-001';
select id into b from gesta_bank.professional_demo where fixture='PRO-DEMO-002';
select x.id into p from gesta_bank.pregnancy_demo x join gesta_bank.profile_demo y on y.id=x.profile_id where y.fixture='AURA-DEMO-001';
select x.id into other_p from gesta_bank.pregnancy_demo x join gesta_bank.profile_demo y on y.id=x.profile_id where y.fixture='AURA-DEMO-002';
if a is null or b is null or p is null or other_p is null then raise exception 'fixtures';end if;
insert into gesta_bank.relationship_demo(professional_id,pregnancy_id,unit_code,mode,approved_at,expires_at) values(a,p,'TEST-CLUES-001','FOLLOW',n,n+interval '30 days') returning id into rel;
insert into gesta_bank.relationship_demo(professional_id,pregnancy_id,unit_code,mode,approved_at,expires_at) values(a,p,'TEST-CLUES-001','TEMPORARY',n,n+interval '30 minutes') returning id into tmp;
v:=gesta_bank.follow_read_demo(a,rel,n,true,true);
if v->>'status' is distinct from 'ALLOWED' then raise exception 'allowed';end if;
if jsonb_array_length(v->'clinical') is distinct from 1 or jsonb_array_length(v->'studies') is distinct from 1 then raise exception 'clinical always';end if;
if v->'diary' is distinct from '[]'::jsonb or v ? 'private_diary' then raise exception 'privacy';end if;
if gesta_bank.follow_read_demo(b,rel,n,true,true)->>'status' is distinct from 'DENIED' then raise exception 'other actor';end if;
if gesta_bank.follow_read_demo(a,rel,n,false,true)->>'status' is distinct from 'DENIED' then raise exception 'MFA';end if;
if gesta_bank.follow_read_demo(a,rel,n,true,false)->>'status' is distinct from 'DENIED' then raise exception 'session';end if;
if gesta_bank.follow_read_demo(a,rel,n,null,true)->>'status' is distinct from 'DENIED' then raise exception 'null';end if;
if gesta_bank.follow_read_demo(a,tmp,n+interval '30 minutes',true,true)->>'status' is distinct from 'DENIED' then raise exception 'temporary expiry';end if;
insert into gesta_bank.study_demo(pregnancy_id,kind,fixture,verified,recorded_at) values(p,'USG','STUDY-DEMO-002',true,n+interval '1 day'),(p,'LAB','STUDY-DEMO-003',false,n),(other_p,'LAB','STUDY-DEMO-004',true,n);
if jsonb_array_length(gesta_bank.follow_read_demo(a,rel,n,true,true)->'studies') is distinct from 1 then raise exception 'future unverified foreign';end if;
v:=gesta_bank.follow_read_demo(a,rel,n+interval '2 days',true,true);
if jsonb_array_length(v->'studies') is distinct from 2 then raise exception 'new study';end if;
update gesta_bank.relationship_demo set diary_shared=true where id=rel;
v:=gesta_bank.follow_read_demo(a,rel,n+interval '2 days',true,true);
if jsonb_array_length(v->'diary') is distinct from 1 or v ? 'private_diary' then raise exception 'shared only';end if;
update gesta_bank.relationship_demo set diary_shared=false where id=rel;
if gesta_bank.follow_read_demo(a,rel,n+interval '2 days',true,true)->'diary' is distinct from '[]'::jsonb then raise exception 'withdraw diary';end if;
update gesta_bank.professional_demo set status='SUSPENDED' where id=a;
if gesta_bank.follow_read_demo(a,rel,n+interval '2 days',true,true)->>'status' is distinct from 'DENIED' then raise exception 'suspended';end if;
update gesta_bank.professional_demo set status='VERIFIED',unit_code='TEST-CLUES-002' where id=a;
if gesta_bank.follow_read_demo(a,rel,n+interval '2 days',true,true)->>'status' is distinct from 'DENIED' then raise exception 'assignment';end if;
update gesta_bank.professional_demo set unit_code='TEST-CLUES-001' where id=a;
update gesta_bank.relationship_demo set revoked_at=n+interval '2 days' where id=rel;
if gesta_bank.follow_read_demo(a,rel,n+interval '3 days',true,true)->>'status' is distinct from 'DENIED' then raise exception 'revoke';end if;
if (select count(*) from gesta_bank.access_audit_demo where relationship_id=rel and result='DENIED')<6 then raise exception 'audit';end if;
if exists(select 1 from pg_class c join pg_namespace s on s.oid=c.relnamespace where s.nspname='gesta_bank' and c.relkind='r' and (not c.relrowsecurity or has_table_privilege('anon',c.oid,'SELECT') or has_table_privilege('authenticated',c.oid,'SELECT'))) then raise exception 'grants';end if;
if has_function_privilege('anon','gesta_bank.follow_read_demo(uuid,uuid,timestamptz,boolean,boolean)','EXECUTE') or has_function_privilege('authenticated','gesta_bank.follow_read_demo(uuid,uuid,timestamptz,boolean,boolean)','EXECUTE') then raise exception 'rpc';end if;
end $$;
select 19 as checks,'PASS' as result;
rollback;